#!/bin/bash
# Desktop smoke test, run as the logged-in user in the harness screenshot boot.
# Prints "SMOKE: ok|FAIL <name>" lines and a final "SMOKE: DONE fails=N".
export XDG_RUNTIME_DIR=/run/user/$(id -u)
# Use the Hyprland instance that answers (newest first). After a VM stall the session can be
# restarted, leaving a dead instance dir behind; wait up to 3 min for a live one.
for _ in $(seq 90); do
  for HYPRLAND_INSTANCE_SIGNATURE in $(ls -t "$XDG_RUNTIME_DIR/hypr" 2>/dev/null); do
    export HYPRLAND_INSTANCE_SIGNATURE; timeout 5 hyprctl version >/dev/null 2>&1 && break 2
  done; sleep 2
done
echo "SMOKE: diag instance=$HYPRLAND_INSTANCE_SIGNATURE of $(ls "$XDG_RUNTIME_DIR/hypr" 2>/dev/null | wc -l) up=$(cut -d' ' -f1 /proc/uptime)"
WAYLAND_DISPLAY=$(ls "$XDG_RUNTIME_DIR" | grep -E '^wayland-[0-9]+$' | head -1); export WAYLAND_DISPLAY
wblog=$XDG_RUNTIME_DIR/graphite-waybar.log
qslog=$XDG_RUNTIME_DIR/qs.cur
# Hyprland 0.56 `hyprctl layers`: "... xywh: X Y W H, a: 1, namespace: graphite-bar, pid: N"
# default bar is Quickshell (namespace graphite-bar); BARNS=waybar for the opt-out checks
BARNS=graphite-bar
# hyprctl answers empty now and then under TCG load: retry until it lists layers
hlayers() { local o; for _ in 1 2 3 4 5; do o=$(timeout 10 hyprctl layers 2>/dev/null); grep -q 'namespace:' <<<"$o" && { echo "$o"; return; }; sleep 2; done; }
barup() { for _ in $(seq "${1:-30}"); do hlayers | grep -q "namespace: $BARNS," && return 0; sleep 2; done; return 1; }
qserr() { grep -aE 'ERROR|[Cc]aused by|[Ff]ailed to load configuration' "$qslog" 2>/dev/null | grep -av 'WARN\|qt.svg' | head -4 | tr '\n' '|' | cut -c1-400; }
fails=0
pkill -x hypridle 2>/dev/null   # no idle lock during the test (hyprlock crashes under TCG, see roadmap notes)
# hypridle can start after this line under TCG (exec-once is slow): keep it away for the whole run
( for _ in $(seq 720); do pkill -x hypridle 2>/dev/null; sleep 10; done ) >/dev/null 2>&1 &
wbtree() { for p in $(pgrep -x waybar); do echo -n "[$p ppid=$(ps -o ppid= -p $p|tr -d ' ') parent=$(ps -o comm= -p $(ps -o ppid= -p $p) 2>/dev/null) cg=$(cut -d: -f3 /proc/$p/cgroup|sed 's|.*/||') start=$(ps -o lstart= -p $p|awk '{print $4}')] "; done; }
check() { if eval "$2" >/dev/null 2>&1; then echo "SMOKE: ok   $1"; else echo "SMOKE: FAIL $1"; fails=$((fails+1)); fi; }
check "Hyprland running" 'pgrep -x Hyprland'
check "hyprctl answers" 'hyprctl version'
# Graphite's config must be what Hyprland loaded: an autogenerated hyprland.lua (Hyprland 0.57+
# ignores hyprland.conf) leaves no binds/bar/first-boot and must not pass as slow-VM noise.
hyprcfg() { [ ! -f ~/.config/hypr/hyprland.lua ] && for _ in $(seq 10); do [ "$(timeout 10 hyprctl binds 2>/dev/null | grep -c '^bind')" -gt 0 ] && return 0; sleep 3; done; return 1; }
echo "SMOKE: diag hyprland: $(hyprctl version 2>&1 | head -1 | cut -c1-120) lua-config: $([ -f ~/.config/hypr/hyprland.lua ] && echo PRESENT-autogenerated || echo none) binds: $(timeout 10 hyprctl binds 2>/dev/null | grep -c '^bind')"
check "CONFIG: Graphite hyprland config loaded (no autogenerated hyprland.lua, binds present)" 'hyprcfg'
# first-boot setup (desk-7): opens at the first login, then never again once finished
for _ in $(seq 60); do timeout 10 hyprctl clients 2>/dev/null | grep -q "title: Graphite Setup" && break; sleep 3; done
echo "SMOKE: SHOT firstboot"; sleep 5
check "first-boot setup opens at the first login" 'timeout 10 hyprctl clients | grep -q "title: Graphite Setup"'
check "first-boot: not marked done yet" '[ "$(graphite-firstboot status)" = done=no ]'
timeout 10 qs ipc -c graphite-firstboot call firstboot step 2 >/dev/null 2>&1; sleep 3
echo "SMOKE: SHOT firstboot-privacy"; sleep 3
check "first-boot: privacy toggles (recent files off and on)" 'graphite-firstboot privacy set recent off && grep -q "gtk-recent-files-enabled=false" ~/.config/gtk-3.0/settings.ini && graphite-firstboot privacy set recent on && [ "$(graphite-firstboot privacy get | grep -c =on)" = 3 ]'
check "first-boot: news opt-out is honored by graphite update" 'graphite-firstboot privacy set news off && [ -f ~/.config/graphite/privacy/no-news ] && graphite-firstboot privacy set news on && [ ! -f ~/.config/graphite/privacy/no-news ]'
check "first-boot: profiles and Secure Boot hint answer" '[ "$(graphite-firstboot profiles | grep -cE "^(gaming|creator|dev|nvidia)=(installed|available)$")" = 4 ] && graphite-firstboot secureboot | grep -qi "secure boot"'
check "first-boot: bundled wallpapers listed" '[ -n "$(graphite-firstboot wallpapers)" ]'
graphite-firstboot finish >/dev/null 2>&1
for _ in $(seq 10); do ! timeout 10 hyprctl clients | grep -q "title: Graphite Setup" && break; sleep 3; done
check "first-boot: finish closes it and marks it done" '! timeout 10 hyprctl clients | grep -q "title: Graphite Setup" && [ "$(graphite-firstboot status)" = done=yes ]'
check "first-boot: auto does not reopen once done" 'graphite-firstboot auto; sleep 5; ! pgrep -f "qs -c graphite-firstboot"'
check "bar (quickshell, default) loaded and mapped" 'barup 90 && pgrep -x qs && ! pgrep -x waybar'
check "quickshell bar config loads without QML errors" '[ -z "$(qserr)" ]'
echo "SMOKE: diag qs errors: $(qserr)"
barup 1 || echo "SMOKE: diag login bar: $(wbtree) gb=$(pgrep -af graphite-bar | tr '\n' ' ') log: $(grep -a 'graphite-bar\|configure' $wblog 2>/dev/null | tail -12 | tr '\n' '|') cur: $(tail -5 $qslog 2>/dev/null | tr '\n' '|') jr: $(journalctl -b -t graphite-bar --no-pager -o cat 2>/dev/null | tail -8 | tr "\n" "|") load: $(cut -d' ' -f1-3 /proc/loadavg) up: $(cut -d' ' -f1 /proc/uptime)"
hclients() { local o; for _ in 1 2 3 4 5; do o=$(timeout 10 hyprctl clients 2>/dev/null); [ -n "$o" ] && { echo "$o"; return; }; sleep 2; done; }
nkitty() { hclients | grep -c "class: kitty"; }
before=$(pgrep -cx kitty)
for _ in 1 2 3; do  # a dispatch can be lost when hyprctl gets no answer under TCG load
  timeout 15 hyprctl dispatch exec kitty >/dev/null 2>&1
  for _ in $(seq 40); do [ "$(pgrep -cx kitty)" -gt "$before" ] && [ "$(nkitty)" -gt 0 ] && break 2; sleep 3; done
  [ "$(pgrep -cx kitty)" -gt "$before" ] && break   # started but not mapped yet: wait below instead of spawning more
done
for _ in $(seq 60); do [ "$(nkitty)" -gt 0 ] && break; sleep 3; done   # slow first map under load
check "terminal opens via dispatch (Super+Return action)" '[ "$(pgrep -cx kitty)" -gt "$before" ] && [ "$(nkitty)" -gt 0 ]'
pkill -x kitty 2>/dev/null; sleep 3
echo "SMOKE: diag layers: $(hyprctl layers 2>/dev/null | grep -o 'namespace: [a-z-]*' | tr '\n' ' ' | cut -c1-300)"
# desktop for the screenshots: fastfetch (logo) + a second tiled terminal
hyprctl dispatch exec "kitty -o font_size=8.5 --hold fastfetch" >/dev/null 2>&1; sleep 8
hyprctl dispatch exec kitty >/dev/null 2>&1; sleep 8
check "network: default route" 'ip route | grep -q "^default"'
check "network: reach host" 'curl -fsS -m 10 -o /dev/null @HOST@/selftest.sh'
check "DRM device present" 'ls /dev/dri/card*'
drv=$(basename "$(readlink -f /sys/class/drm/card*/device/driver 2>/dev/null | head -1)")
echo "SMOKE: diag drm driver=$drv"
hl="$XDG_RUNTIME_DIR/hypr/$HYPRLAND_INSTANCE_SIGNATURE/hyprland.log"
gl=$(grep -aiohE "GL_RENDERER[^\"]{0,80}|renderer: [^\"]{0,80}" "$hl" 2>/dev/null | head -1)
[ -n "$gl" ] || gl=$(grep -aohE "Renderer[^\"]{0,80}" "$hl" 2>/dev/null | head -1)
echo "SMOKE: diag gl=$gl"
check "GL renderer reported by Hyprland" '[ -n "$gl" ]'
# theme switch must leave a drawn bar (regression: waybar missing after a switch)
timeout 180 graphite-theme set graphite-nord >/dev/null 2>&1 || echo "SMOKE: diag theme nord rc=$?"; barup 30; sleep 5
echo "SMOKE: SHOT theme-nord"; sleep 10
check "bar back after theme switch (layer mapped)" 'barup 5'
echo "SMOKE: diag waybar after nord: $(wbtree)"
barup 1 || echo "SMOKE: diag waybar log: $(tail -5 $wblog 2>/dev/null | tr '\n' '|')"
nord=$(sed -n 's/^accent *= *"\(#[0-9a-fA-F]*\)".*/\1/p' /usr/share/graphite/themes/graphite-nord/colors.toml)
check "kitty colours follow theme (nord accent $nord)" 'grep -qi "$nord" ~/.config/graphite/current/kitty.conf'
# desk-5: wallpaper-derived theme (offline palette extraction), then back to teal below
command -v graphite-palette >/dev/null && python3 -c 'import PIL' 2>/dev/null || echo "SMOKE: diag palette deps missing"
timeout 400 graphite theme from-wallpaper /usr/share/backgrounds/graphite/graphite-violet.png >/dev/null 2>&1 || echo "SMOKE: diag from-wallpaper rc=$?"
wpacc=$(sed -n 's/^accent *= *"\(#[0-9a-fA-F]*\)".*/\1/p' ~/.config/graphite/themes/wallpaper/colors.toml 2>/dev/null)
echo "SMOKE: diag from-wallpaper accent=$wpacc theme=$(graphite-theme current)"
check "theme from-wallpaper writes a palette and applies it" '[ "$(graphite-theme current)" = wallpaper ] && [ -n "$wpacc" ] && grep -qi "$wpacc" ~/.config/graphite/current/kitty.conf'
check "from-wallpaper theme uses the wallpaper" 'grep -q "themes/wallpaper/wallpaper.png" ~/.config/graphite/current/wallpaper'
barup 60; echo "SMOKE: SHOT theme-from-wallpaper"; sleep 10
echo "SMOKE: diag t=$(date +%T) teal switch start"
timeout 180 graphite-theme set graphite-teal >/dev/null 2>&1 || echo "SMOKE: diag theme teal rc=$?"
echo "SMOKE: diag t=$(date +%T) teal switch returned"
barup 30; echo "SMOKE: diag t=$(date +%T) barup done"
echo "SMOKE: diag waybar after teal: $(wbtree) units=$(timeout 10 systemctl --user list-units --all 'waybar*' --no-legend 2>/dev/null|tr -s ' '|cut -c1-80)"
check "bar back after switching to graphite-teal" 'barup 5 && [ "$(pgrep -cx qs)" = 1 ]'
echo "SMOKE: diag after teal: qs=[$(pgrep -a qs | tr "\n" "|" | cut -c1-300)] barns=$(timeout 10 hyprctl layers 2>&1 | grep -c "namespace: $BARNS,")"
pgrep -x qs >/dev/null || echo "SMOKE: diag bar log: $(tail -5 $wblog 2>/dev/null | tr '\n' '|')"
# launcher (desk-2): search through IPC, then open it the way Super+Space does
lq() { timeout 25 graphite-launcher query "$1" 2>/dev/null; }
lmapped() { hlayers | grep -q 'namespace: graphite-launcher,'; }
lgone() { local o; o=$(hlayers); grep -q 'namespace: graphite-bar,' <<<"$o" && ! grep -q 'namespace: graphite-launcher,' <<<"$o"; }
# hyprctl can answer empty for minutes right after a theme switch reload under TCG (h19): retry ~4 min
spacebound() { for _ in $(seq 20); do timeout 10 hyprctl binds 2>/dev/null | grep -i -A12 "key: space" | grep -q "arg: graphite-launcher" && return 0; sleep 3; done; return 1; }
echo "SMOKE: diag launcher: calc=[$(lq '2+3*4')] app=[$(lq kitty)] cmd=[$(lq '>lock')] run=[$(lq '>echo hi')] theme=[$(lq 'theme: nord')]"
echo "SMOKE: diag qs procs: $(pgrep -a qs | tr '\n' '|' | cut -c1-300) binds-space: $(timeout 10 hyprctl binds 2>&1 | grep -i -A12 'key: space' | tr -s '\n\t' '  ' | cut -c1-400) layers: $(timeout 10 hyprctl layers 2>&1 | grep -o 'namespace: [a-z-]*' | tr '\n' ' ')"
check "Super+Space is bound to graphite-launcher" 'spacebound'
check "launcher calculator: 2+3*4 = 14" '[ "$(lq "2+3*4")" = "calc: 14" ]'
check "launcher calculator: = sqrt(16)+2^3 = 12" '[ "$(lq "= sqrt(16)+2^3")" = "calc: 12" ]'
check "launcher finds apps (kitty)" '[ "$(lq kitty)" = "app: kitty" ]'
check "launcher commands (>lock)" '[ "$(lq ">lock")" = "cmd: Lock screen" ]'
check "launcher runs shell commands (>echo hi)" '[ "$(lq ">echo hi")" = "cmd: Run: echo hi" ]'
check "launcher lists themes" '[ "$(lq "theme: nord")" = "cmd: Theme: graphite-nord" ]'
# under TCG a dispatch (or the first map) can be lost: retry the open up to 3 times, and
# require the layer to stay mapped across two reads
lopen() { timeout 10 hyprctl dispatch exec "graphite-launcher open >/tmp/gl.log 2>&1" >/dev/null 2>&1
  for _ in $(seq 30); do lmapped && sleep 2 && lmapped && return 0; sleep 3; done; return 1; }
for a in 1 2 3; do lopen && break
  echo "SMOKE: diag launcher open attempt $a: isOpen=$(timeout 5 qs ipc -c graphite-bar call launcher isOpen 2>&1) layers=$(hlayers | grep -o 'namespace: [a-z-]*' | tr '\n' ' ')"
  timeout 25 graphite-launcher close >/dev/null 2>&1; sleep 3; done
timeout 5 qs ipc -c graphite-bar call launcher query "" >/dev/null 2>&1   # show the app list in the shot
echo "SMOKE: SHOT launcher"; sleep 8
check "launcher opens (layer graphite-launcher mapped)" 'lmapped'
check "launcher opened on the first try (attempts: $a)" '[ "$a" = 1 ]'
lmapped || echo "SMOKE: diag launcher open: isOpen=$(timeout 5 qs ipc -c graphite-bar call launcher isOpen 2>&1) gl.log=$(tr '\n' '|' </tmp/gl.log 2>/dev/null | cut -c1-200) layers: $(timeout 10 hyprctl layers 2>&1 | grep -o 'namespace: [a-z-]*' | tr '\n' ' ') qslog: $(grep -a -i 'launcher\|error' "$qslog" 2>/dev/null | tail -5 | tr '\n' '|' | cut -c1-400)"
timeout 25 graphite-launcher close >/dev/null 2>&1; for _ in $(seq 10); do lgone && break; sleep 3; done
check "launcher closes" 'lgone'
# notifications (desk-3): Quickshell is the daemon; popups, center (Super+N) and do-not-disturb
nq() { timeout 25 graphite-notify "$@" 2>/dev/null; }
nmapped() { hlayers | grep -q "namespace: $1,"; }
nsend() { timeout 30 notify-send -a smoke "$@" >/dev/null 2>&1; }
graphite-notify dnd off >/dev/null 2>&1
# critical: stays until dismissed, so the popup is still up when checked under TCG
n0=$(nq count); nsend -u critical "smoke hello" "from the harness"
for _ in $(seq 20); do [ "$(nq count)" -gt "${n0:-0}" ] 2>/dev/null && break; sleep 2; done
check "notifications go to Quickshell (graphite-notify count rises)" '[ "$(nq count)" -gt "${n0:-0}" ]'
check "mako is not running with the Quickshell bar" '! pgrep -x mako'
check "notification daemon is the Quickshell bar" 'busctl --user status org.freedesktop.Notifications 2>/dev/null | grep -q "^Comm=qs"'
for _ in $(seq 20); do nmapped graphite-notifications && break; sleep 3; done
echo "SMOKE: SHOT notification-popup"; sleep 5
check "notification popup shows (layer graphite-notifications)" 'nmapped graphite-notifications'
check "Super+N is bound to the notification center" '(for _ in 1 2 3 4 5; do timeout 10 hyprctl binds 2>/dev/null | grep -i -A12 "key: n$" | grep -q "arg: graphite-notify center" && exit 0; sleep 2; done; exit 1)'
echo "SMOKE: diag notify: dnd=[$(nq dnd)] popups=[$(nq popups)] count=[$(nq count)]"
check "do-not-disturb on" '[ "$(nq dnd on)" = on ] && [ -e "$HOME/.local/state/graphite/dnd" ]'
p0=$(nq popups); c0=$(nq count); nsend "smoke quiet"; sleep 6
echo "SMOKE: diag dnd: p0=[$p0] c0=[$c0] popups=[$(nq popups)] count=[$(nq count)] dnd=[$(nq dnd)]"
check "do-not-disturb holds popups back but keeps the notification" '[ "$(nq popups)" -le "${p0:-0}" ] && [ "$(nq count)" -gt "${c0:-0}" ]'
check "do-not-disturb off" '[ "$(nq dnd off)" = off ] && [ ! -e "$HOME/.local/state/graphite/dnd" ]'
timeout 10 hyprctl dispatch exec "graphite-notify open" >/dev/null 2>&1
for _ in $(seq 30); do nmapped graphite-notification-center && break; sleep 3; done
echo "SMOKE: SHOT notification-center"; sleep 5
check "notification center opens (layer graphite-notification-center)" 'nmapped graphite-notification-center'
check "notification center lists the notification" 'nq list | grep -q "smoke hello"'
nq close >/dev/null; nq clear >/dev/null
for _ in $(seq 10); do ! nmapped graphite-notification-center && [ "$(nq count)" = 0 ] && break; sleep 3; done
check "notification center closes and clears" '[ "$(nq count)" = 0 ] && ! nmapped graphite-notification-center'
# control center (desk-4): graphite-control backend + Quickshell panel (Super+A)
cst() { timeout 60 graphite-control status 2>/dev/null | sed -n "s/^$1=//p"; }
cq() { timeout 25 qs ipc -c graphite-bar call control "$@" 2>/dev/null; }
echo "SMOKE: diag control: lock=[$(pgrep -x hyprlock)] idle=[$(pgrep -x hypridle)] $(timeout 60 graphite-control status 2>&1 | tr '\n' ' ')"
check "control center status reports every setting" '[ "$(timeout 60 graphite-control status 2>/dev/null | grep -cE "^(volume|muted|brightness|wifi|bluetooth|profile|theme)=")" = 7 ]'
echo "SMOKE: diag binds-a: $(timeout 20 hyprctl binds 2>&1 | grep -i -B3 -A3 'arg: graphite-control' | tr -s '\n\t' '  ' | cut -c1-300)"
check "Super+A is bound to the control center" '(for _ in 1 2 3 4 5; do timeout 10 hyprctl binds 2>/dev/null | grep -i -A12 "key: a$" | grep -q "arg: graphite-control" && exit 0; sleep 3; done; exit 1)'
# the VM has no sound card: give PipeWire a null sink so there is a default output to control
if [ "$(cst volume)" = none ]; then
  timeout 20 pactl load-module module-null-sink sink_name=smoke_null sink_properties=device.description=smoke_null >/dev/null 2>&1
  for _ in $(seq 10); do timeout 10 wpctl status 2>/dev/null | grep -q smoke_null && break; sleep 2; done
  sid=$(timeout 10 wpctl status 2>/dev/null | sed -n 's/^[^0-9]*\([0-9][0-9]*\)\. .*smoke_null.*/\1/p' | head -1)
  [ -n "$sid" ] && timeout 10 wpctl set-default "$sid" >/dev/null 2>&1
  echo "SMOKE: diag null sink id=[$sid] volume=[$(cst volume)]"
fi
v0=$(cst volume)
check "control center sets the volume" '[ "$(timeout 20 graphite-control volume 40)" = 40 ] && [ "$(cst volume)" = 40 ]'
check "control center mutes and unmutes" 'timeout 20 graphite-control volume mute >/dev/null; [ "$(cst muted)" = yes ] && timeout 20 graphite-control volume mute >/dev/null && [ "$(cst muted)" = no ]'
[ -n "$v0" ] && [ "$v0" != none ] && timeout 20 graphite-control volume "$v0" >/dev/null
# Wi-Fi radio and power profile changes go through polkit (allowed for the active desktop
# session, not this serial login): run them in the compositor session like the panel does
dexec() { timeout 15 hyprctl dispatch exec "graphite-control $*" >/dev/null 2>&1; }
waitst() { for _ in $(seq 20); do [ "$(cst "$1")" = "$2" ] && return 0; sleep 3; done; return 1; }
w0=$(cst wifi); w1=$([ "$w0" = on ] && echo off || echo on)
check "control center toggles the Wi-Fi radio" 'dexec wifi toggle; waitst wifi "$w1" && dexec wifi "$w0" && waitst wifi "$w0"'
pr0=$(cst profile)
echo "SMOKE: diag profiles: [$pr0] $(timeout 30 powerprofilesctl list 2>&1 | tr '\n' ' ' | cut -c1-200)"
# powerprofilesctl (python) can take >15 s to answer under TCG and graphite-control then reports
# none and changes nothing: re-dispatch "next" if the profile has not moved after ~1 min
pcycle() { for _ in 1 2 3; do dexec profile next; for _ in $(seq 10); do p=$(cst profile); [ -n "$p" ] && [ "$p" != none ] && [ "$p" != "$pr0" ] && return 0; sleep 3; done; done; return 1; }
check "control center cycles the power profile" '[ "$pr0" != none ] && pcycle && (for _ in 1 2 3; do dexec profile "$pr0"; waitst profile "$pr0" && exit 0; done; exit 1)'
echo "SMOKE: diag profile after cycle: [$(cst profile)]"
check "bluetooth.service enabled" 'systemctl is-enabled -q bluetooth.service'
# hardware-dependent: the VM has no Bluetooth adapter, so only check the reported state when one exists
if [ -n "$(timeout 20 bluetoothctl list 2>/dev/null)" ]; then
  check "control center reports Bluetooth" '[ -n "$(cst bluetooth)" ]'
else echo "SMOKE: skip control center reports Bluetooth (no adapter in the VM; status=$(cst bluetooth))"; fi
timeout 10 hyprctl dispatch exec "graphite-control open" >/dev/null 2>&1
for _ in $(seq 40); do nmapped graphite-control-center && break; sleep 3; done
echo "SMOKE: diag control open: isOpen=[$(cq isOpen)] layers=[$(hlayers | grep -o 'namespace: [a-z-]*' | tr '\n' ' ')]"
echo "SMOKE: SHOT control-center"; sleep 5
check "control center opens (layer graphite-control-center)" 'nmapped graphite-control-center && [ "$(cq isOpen)" = true ]'
cq close >/dev/null
for _ in $(seq 10); do ! nmapped graphite-control-center && break; sleep 3; done
check "control center closes" '! nmapped graphite-control-center'
th0=$(cst theme)
# judge the saved theme, not the toggle's stdout: under heavy TCG load the bar restart inside
# graphite-theme can outlast a timeout, which used to blank the output (h18: a 79 min stall)
tt() { timeout 900 graphite-control theme-toggle >/dev/null 2>&1; graphite-theme current; }
check "control center theme toggle switches to light and back" '[ "$(tt)" = graphite-light ] && [ "$(tt)" = "$th0" ]'
for _ in $(seq 40); do [ -n "$(cq isOpen)" ] && break; sleep 3; done
check "bar is back after the theme toggle" '[ -n "$(cq isOpen)" ]'
# bar widgets: tray/network/audio/battery come from the services, check the backends answer
check "upower daemon answers (battery widget backend)" 'timeout 10 upower -e'
check "graphite bar status reports quickshell" 'graphite bar status | grep -q "bar: quickshell"'
echo "SMOKE: SHOT quickshell-bar"; sleep 5
# opt-out: Waybar replaces the Quickshell bar, then back to the default
timeout 900 graphite bar waybar >/dev/null 2>&1 || echo "SMOKE: diag bar waybar rc=$?"
BARNS=waybar; barup 90
echo "SMOKE: diag optout: choice=$(cat ~/.config/graphite/bar) qs=$(pgrep -cx qs) waybar=$(pgrep -cx waybar) log=$(tail -4 "${XDG_RUNTIME_DIR:-/tmp}/graphite-waybar.log" 2>/dev/null | tr '\n' '|')"
echo "SMOKE: SHOT waybar-optout"; sleep 5
check "opt-out: graphite bar waybar maps waybar, no quickshell" 'barup 5 && [ "$(pgrep -cx waybar)" = 1 ] && ! pgrep -x qs'
barup 1 || echo "SMOKE: diag waybar log: $(tail -5 $wblog 2>/dev/null | tr '\n' '|')"
check "opt-out: mako shows notifications with Waybar" '(for _ in $(seq 10); do pgrep -x mako >/dev/null && exit 0; sleep 2; done; exit 1)'
# without Quickshell the launcher falls back to rofi
for _ in 1 2 3; do
  timeout 15 hyprctl dispatch exec graphite-launcher >/dev/null 2>&1
  for _ in $(seq 20); do timeout 10 hyprctl layers 2>/dev/null | grep -q 'namespace: rofi,' && break 2; pgrep -x rofi >/dev/null && sleep 3 && continue; sleep 2; done
done
check "launcher falls back to rofi with Waybar" '(for _ in 1 2 3; do timeout 10 hyprctl layers | grep -q "namespace: rofi," && exit 0; sleep 3; done; exit 1)'
pkill -x rofi 2>/dev/null; sleep 2
timeout 900 graphite bar quickshell >/dev/null 2>&1 || echo "SMOKE: diag bar quickshell rc=$?"
BARNS=graphite-bar; barup 90
check "back to default: quickshell bar mapped, waybar gone" 'barup 5 && [ "$(pgrep -cx qs)" = 1 ] && ! pgrep -x waybar && [ "$(cat ~/.config/graphite/bar)" = quickshell ]'
# settings app (desk-6): graphite-settings backend + Quickshell window (Super+I)
check "settings: settings.conf is generated and sourced" '[ -f ~/.config/graphite/settings.conf ] && grep -q "^source = ~/.config/graphite/settings.conf" ~/.config/hypr/hyprland.conf'
check "Super+I is bound to Settings" '(for _ in 1 2 3 4 5; do timeout 10 hyprctl binds 2>/dev/null | grep -i -A12 "key: i$" | grep -q "arg: graphite-settings" && exit 0; sleep 3; done; exit 1)'
check "settings: get reports every key" '[ "$(timeout 30 graphite-settings get | grep -cE "^(scale|kb_layout|kb_variant|sensitivity|natural_scroll|follow_mouse|theme|bar|wifi)=")" -ge 9 ]'
# Hyprland 0.56 prints bools as "bool: true|false" (older: "int: 1|0"); hyprctl can lag under TCG, so poll
hopt() { for _ in $(seq 10); do timeout 20 hyprctl getoption "$1" 2>/dev/null | grep -qE "$2" && return 0; sleep 3; done; return 1; }
check "settings: natural scrolling applies to Hyprland" 'timeout 90 graphite-settings set natural_scroll true && hopt input:touchpad:natural_scroll "(int: 1|bool: true)\$" && timeout 90 graphite-settings set natural_scroll false && hopt input:touchpad:natural_scroll "(int: 0|bool: false)\$"'
check "settings: pointer speed applies to Hyprland" 'timeout 90 graphite-settings set sensitivity 0.25 && hopt input:sensitivity "float: 0\.25" && timeout 90 graphite-settings set sensitivity 0'
echo "SMOKE: diag settings: $(timeout 20 hyprctl getoption input:touchpad:natural_scroll 2>&1 | head -1) | $(timeout 20 hyprctl getoption input:sensitivity 2>&1 | head -1)"
check "settings: rejects a bad value" '! timeout 30 graphite-settings set scale banana 2>/dev/null'
check "settings: about reports the system" 'timeout 30 graphite-settings about | grep -q "^kernel="'
timeout 10 hyprctl dispatch exec "graphite-settings open" >/dev/null 2>&1
for _ in $(seq 40); do timeout 10 hyprctl clients 2>/dev/null | grep -q "title: Graphite Settings" && break; sleep 3; done
echo "SMOKE: SHOT settings"; sleep 5
check "settings window opens" 'timeout 10 hyprctl clients | grep -q "title: Graphite Settings"'
timeout 10 qs ipc -c graphite-settings call settings page about >/dev/null 2>&1; sleep 3
echo "SMOKE: SHOT settings-about"; sleep 3
timeout 10 qs ipc -c graphite-settings call settings page store >/dev/null 2>&1; sleep 5
check "settings: theme store page opens" '[ "$(timeout 10 qs ipc -c graphite-settings call settings current 2>/dev/null)" = store ]'
echo "SMOKE: SHOT settings-store"; sleep 3
timeout 10 qs ipc -c graphite-settings call settings search vlc >/dev/null 2>&1
check "settings: apps page searches the repos" '(for _ in $(seq 20); do [ "$(timeout 10 qs ipc -c graphite-settings call settings results 2>/dev/null)" -gt 0 ] 2>/dev/null && exit 0; sleep 3; done; exit 1)'
echo "SMOKE: SHOT settings-apps"; sleep 3
timeout 20 graphite-settings close >/dev/null 2>&1
for _ in $(seq 10); do ! timeout 10 hyprctl clients | grep -q "title: Graphite Settings" && break; sleep 3; done
check "settings window closes" '! timeout 10 hyprctl clients | grep -q "title: Graphite Settings"'
# GPU auto-setup (game-1): the VM's virtual GPU needs nothing; fixtures check the per-vendor plans
check "gpu: status lists the VM's display controller" 'timeout 60 graphite gpu status | grep -q "^gpu 1:"'
check "gpu: nothing to install for the virtual GPU" '[ "$(timeout 60 graphite gpu plan)" = "nothing to install" ]'
fx=$(mktemp); printf '%s\n' '00:02.0 VGA compatible controller [0300]: Intel Corporation Alder Lake-P GT2 [Iris Xe Graphics] [8086:46a6] (rev 0c)' '	Kernel driver in use: i915' '01:00.0 3D controller [0302]: NVIDIA Corporation GA107M [GeForce RTX 3050 Mobile] [10de:25a2] (rev a1)' '	Kernel driver in use: nouveau' > "$fx"
check "gpu: Intel + RTX laptop plan adds nvidia-open" 'p=$(GRAPHITE_LSPCI=$fx graphite gpu plan); grep -qE "^nvidia-open(-dkms)?$" <<<"$p" && grep -qx lib32-nvidia-utils <<<"$p" && ! grep -qx vulkan-nouveau <<<"$p"'
printf '%s\n' '04:00.0 VGA compatible controller [0300]: NVIDIA Corporation GP106 [GeForce GTX 1060 6GB] [10de:1c03] (rev a1)' > "$fx"
check "gpu: pre-Turing NVIDIA stays on nouveau" 'p=$(GRAPHITE_LSPCI=$fx graphite gpu status); grep -q "pre-Turing" <<<"$p" && ! grep -q nvidia-open <<<"$p"'
rm -f "$fx"
# low-latency audio (game-2): PipeWire picks up the preset after the user services restart
aq() { for _ in $(seq 20); do v=$(timeout 10 pw-metadata -n settings 0 clock.quantum 2>/dev/null | sed -n "s/.*value:'\([0-9]*\)'.*/\1/p"); [ "$v" = "$1" ] && return 0; sleep 3; done; echo "SMOKE: diag audio quantum=[$v] want $1"; return 1; }
check "audio: rtkit and the realtime group are set up" 'pacman -Qq rtkit realtime-privileges && id -nG | grep -qw realtime'
check "audio: lowlatency preset sets PipeWire quantum 64" 'timeout 150 graphite audio lowlatency >/dev/null && aq 64'
echo "SMOKE: diag audio: $(timeout 60 graphite audio status 2>&1 | head -2 | tr '\n' ' ')"
check "audio: status reports the preset" 'timeout 60 graphite audio status | grep -q "preset:   lowlatency (quantum 64)"'
check "audio: default preset restores quantum 1024" 'timeout 150 graphite audio default >/dev/null && aq 1024 && [ ! -f ~/.config/pipewire/pipewire.conf.d/90-graphite-latency.conf ]'
check "audio: rejects a bad quantum" '! graphite audio lowlatency 7 2>/dev/null'
# performance options (game-3): read-only/dry parts; the preset is written to a scratch root
check "perf: status lists linux and linux-lts" 'graphite perf status | grep -q "kernels:  linux linux-lts"'
check "perf: kernel plan offers linux-zen" 'graphite perf kernel plan | grep -q "linux-zen linux-zen-headers"'
check "perf: gaming preset written and removed" 'r=$(mktemp -d) && GRAPHITE_ROOT=$r graphite perf tune gaming >/dev/null && grep -q "^kernel.split_lock_mitigate = 0" $r/etc/sysctl.d/95-graphite-perf.conf && GRAPHITE_ROOT=$r graphite perf status | grep -q "tuning:   gaming" && GRAPHITE_ROOT=$r graphite perf tune default >/dev/null && [ ! -e $r/etc/sysctl.d/95-graphite-perf.conf ]'
check "perf: preset keys exist on this kernel" '(for k in kernel.split_lock_mitigate vm.compaction_proactiveness vm.dirty_bytes kernel.sched_autogroup_enabled; do [ -e /proc/sys/${k//.//} ] || [ $k = kernel.split_lock_mitigate ] || exit 1; done)'
# workload profiles (game-4). The harness installs --profile desktop (full only with
# tests/qemu-install.py --profile full), so gaming is normally "available" here: then check the
# signed repo's graphite-gaming package carries gamescope and the Steam (gamescope) session.
if pacman -Qq graphite-gaming >/dev/null 2>&1; then
  check "profile: status shows gaming installed, creator available" 'graphite profile status | grep -qx gaming=installed && graphite profile status | grep -qx creator=available'
  check "profile: gamescope session in the login screen" 'pacman -Qq gamescope && grep -q "^Exec=gamescope" /usr/share/wayland-sessions/graphite-gamescope.desktop'
else
  check "profile: status shows gaming available, creator available" 'graphite profile status | grep -qx gaming=available && graphite profile status | grep -qx creator=available'
  gpkg=$(mktemp -d)
  check "profile: gamescope session in the login screen" 'pacman -Si graphite-gaming | grep -E "^Depends On" | grep -qw gamescope && graphite profile plan gaming | grep -qw gamescope && u=$(pacman -Sp -dd --print-format %l graphite-gaming 2>/dev/null | tail -1) && case $u in file://*) cp "${u#file://}" $gpkg/g.pkg;; *) timeout 120 curl -fsSL "$u" -o $gpkg/g.pkg;; esac && bsdtar -xOf $gpkg/g.pkg usr/share/wayland-sessions/graphite-gamescope.desktop | grep -q "^Exec=gamescope"'
  echo "SMOKE: diag profile pkg: $(pacman -Sp -dd --print-format %l graphite-gaming 2>&1 | tail -1)"
  rm -rf "$gpkg"
fi
check "profile: creator plan lists OBS" 'graphite profile plan creator | grep -q "obs-studio"'
check "profile: rejects an unknown profile" '! graphite profile plan bogus 2>/dev/null'
# local settings sync (eco-1): export, change a file, import restores it and keeps a backup
check "sync: export, import restores and backs up" 'd=$(mktemp -d) && graphite sync export $d/s.tar.gz >/dev/null && tar -tzf $d/s.tar.gz | grep -q "^hypr/hyprland.conf" && ! tar -tzf $d/s.tar.gz | grep -qE "(^|/)(\.ssh|\.gnupg|keyrings)/" && cp ~/.config/hypr/hyprland.conf $d/orig && echo "# sync-test" >> ~/.config/hypr/hyprland.conf && graphite sync import $d/s.tar.gz --yes >/dev/null && cmp -s ~/.config/hypr/hyprland.conf $d/orig && ls ~/.local/state/graphite/sync-backup-*.tar.gz'
check "sync: git export commits" '! command -v git || { d=$(mktemp -d) && graphite sync export --git $d/repo >/dev/null && [ "$(git -C $d/repo rev-list --count HEAD)" = 1 ] && [ -f $d/repo/config/hypr/hyprland.conf ]; }'
check "sync: import refuses a folder without settings" '! graphite sync import "$(mktemp -d)" --yes 2>/dev/null'
# theme store (eco-2): graphite-theme-* packages in the signed repo
check "theme store: browse lists the store themes" '[ "$(timeout 30 graphite theme browse --tsv | grep -cE "^graphite-(gruvbox|rosepine|solarized)[[:space:]].+[[:space:]](installed|available)$")" = 3 ]'
check "theme store: store themes are not installed by default" '! graphite theme list | grep -q gruvbox'
check "theme store: rejects a bad name" '! graphite theme install ../etc 2>/dev/null && ! graphite theme install graphite-nosuch 2>/dev/null'
# app store (eco-3): curated list + pacman search, no installs in the test
check "apps: curated list with states" '[ "$(graphite apps list --tsv | grep -cE "	(pacman|flatpak)	.*	(installed|available)$")" -ge 20 ]'
check "apps: search finds a repo package" 'timeout 60 graphite apps search vlc --tsv | grep -q "^vlc	pacman	"'
check "apps: rejects a bad id" '! graphite apps install "a;b" 2>/dev/null && ! graphite apps install no-such-package-xyz 2>/dev/null'
echo "SMOKE: DONE fails=$fails"
